from typing import List

class Solution:
    def subarraysWithKDistinct(self, nums: List[int], k: int) -> int:
        ans = 0
        for left in range(len(nums)):
            seen = set()
            for right in range(left, len(nums)):
                seen.add(nums[right])
                if len(seen) == k:
                    ans += 1
                elif len(seen) > k:
                    break
        return ans

